    "sentences": [
      {
        "text": "前370，魏之内乱。",
        "start": 0,
        "end": 4.06
      },
      {
        "text": "武侯卒而未立太子，公中缓与惠王争立；",
        "start": 4.06,
        "end": 8.9381
      },
      {
        "text": "韩赵合兵，败魏于浊泽而围惠王。",
        "start": 9.1581,
        "end": 13.36
      },
      {
        "text": "二国意见不合，引兵而去，魏得以不分。",
        "start": 13.36,
        "end": 17.3728
      }
    ],
