    "sentences": [
      {
        "text": "前246，始凿郑国渠。",
        "start": 0,
        "end": 4.28
      },
      {
        "text": "韩以疲秦之计使水工郑国凿渠。",
        "start": 4.28,
        "end": 7.4707
      },
      {
        "text": "事觉，郑国曰「臣为韩延数岁之命，",
        "start": 7.6907,
        "end": 12.6
      },
      {
        "text": "而为秦建万世之功」——渠成而关中为沃野，秦反以富强。",
        "start": 12.6,
        "end": 19.5316
      }
    ],
